import { createClient } from 'jsr:@supabase/supabase-js@2';
const cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization, x-client-info, apikey, content-type','Access-Control-Allow-Methods':'GET, OPTIONS','Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
Deno.serve(async(req)=>{if(req.method==='OPTIONS')return new Response('ok',{headers:cors});try{const ks=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const sb=createClient(Deno.env.get('SUPABASE_URL')!,ks.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});const u=new URL(req.url),gw=Number(u.searchParams.get('gw')||1);const {data:runs,error:re}=await sb.from('projection_benchmark_runs').select('id,source,source_label,gameweek,captured_at,source_generated_at,url,notes').eq('gameweek',gw).order('captured_at',{ascending:false});if(re)throw re;const latestBySource=new Map<string,any>();for(const r of runs||[]){if(!latestBySource.has(r.source))latestBySource.set(r.source,r)}const latest=[...latestBySource.values()],runIds=latest.map((r:any)=>r.id);const [{data:squad},{data:pbs},{data:tbs},{data:predRun}]=await Promise.all([sb.from('squad_members').select('player_id').eq('active',true),sb.from('player_projection_benchmarks').select('benchmark_run_id,player_id,player_name,team_short,position,expected_points,projected_goals,projected_assists,projected_bonus,defcon_probability').in('benchmark_run_id',runIds),sb.from('team_projection_benchmarks').select('benchmark_run_id,team_id,team_name,projected_goals_for,projected_goals_against,clean_sheet_probability').in('benchmark_run_id',runIds),sb.from('gameweek_prediction_runs').select('id,generated_at').eq('gameweek',gw).eq('frozen',true).order('generated_at',{ascending:false}).limit(1).maybeSingle()]);const ids=(squad||[]).map((x:any)=>x.player_id);let ours:any[]=[];if(predRun){const {data:p}=await sb.from('model_predictions').select('player_id,expected_points,expected_minutes,p_start,p_goal,p_assist,p_clean_sheet,p_dc,p_bonus,features').eq('prediction_run_id',predRun.id).in('player_id',ids);ours=p||[]}const {data:pls}=await sb.from('players').select('id,web_name,position,team_id,teams!inner(short_name,name)').in('id',ids);const runMap=new Map(latest.map((r:any)=>[r.id,r.source])),ourMap=new Map(ours.map((x:any)=>[x.player_id,x]));const rows=(pls||[]).map((p:any)=>{const vals=(pbs||[]).filter((b:any)=>b.player_id===p.id).map((b:any)=>({source:runMap.get(b.benchmark_run_id),xpts:Number(b.expected_points)}));const mean=vals.length?vals.reduce((s:any,x:any)=>s+x.xpts,0)/vals.length:null;const o=ourMap.get(p.id)||null;return {player_id:p.id,name:p.web_name,team:p.teams?.short_name,position:p.position,our_xpts:o?Number(o.expected_points):null,benchmark_mean:mean,benchmark_sources:vals,vs_mean:o&&mean!=null?Number(o.expected_points)-mean:null,our:o}}).sort((a:any,b:any)=>(b.our_xpts??-99)-(a.our_xpts??-99));const matched=rows.filter((x:any)=>x.our_xpts!=null&&x.benchmark_mean!=null),summary={matched_players:matched.length,our_mean:matched.length?matched.reduce((s:any,x:any)=>s+x.our_xpts,0)/matched.length:null,benchmark_mean:matched.length?matched.reduce((s:any,x:any)=>s+x.benchmark_mean,0)/matched.length:null,mean_gap:matched.length?matched.reduce((s:any,x:any)=>s+(x.our_xpts-x.benchmark_mean),0)/matched.length:null};return new Response(JSON.stringify({ok:true,gameweek:gw,sources:latest,summary,players:rows,team_benchmarks:tbs||[]}),{headers:cors})}catch(e){return new Response(JSON.stringify({ok:false,error:e instanceof Error?e.message:String(e)}),{status:500,headers:cors})}});
